[5781] = { en = "Of Forgotten Memories", tier = 4,
  t = "Vergeten herinneringen",
  d = "Om Taelan te helpen terug te krijgen wat hij verloren heeft, moet je voorwerpen uit zijn verleden verzamelen.$B$BHet eerste voorwerp is speelgoed dat ik hem op zijn zevende verjaardag gaf. Het was zijn dierbaarste bezit: een kleine strijdhamer, een precieze kopie van mijn eigen hamer.$B$BToen ik wegens verraad werd verbannen, vertelde zijn moeder hem dat ik gestorven was. Hij werd naar mijn valse graf bij de Undercroft gebracht. Daar begroef hij de hamer, samen met de herinnering aan mij - voor altijd.$B$BJe moet naar de Undercroft gaan en Taelans hamer terughalen.",
  o = "Reis naar de Undercroft - in het zuidelijkste deel van de Eastern Plaguelands - en haal Taelan's Hammer terug. Keer terug naar Tirion Fordring als je opdracht klaar is.",
  p = "Hij moet verlost worden.",
  c = "<Tirion knippert met zijn ogen om zijn tranen tegen te houden.>$B$BHet was het lot dat wij elkaar ontmoetten, $N. Je hebt me gezegend met je goedheid.$b",
  g = { {"dierbaarste", "most cherished (dierbaar)"}, {"bezit", "possession"}, {"strijdhamer", "war hammer"}, {"kopie", "copy, replica"}, {"verraad", "treason, betrayal"}, {"verbannen", "banished"}, {"graf", "grave"}, {"begroef", "buried (begraven)"}, {"terughalen", "to get back, recover"}, {"zuidelijkste", "southernmost"}, {"verlost", "redeemed, saved (verlossen)"}, {"knippert", "blinks (knipperen)"}, {"lot", "fate, destiny"}, {"gezegend", "blessed (zegenen)"}, {"goedheid", "kindness"} },
},

[5065] = { en = "The Lost Tablets of Mosh'aru", tier = 4,
  t = "De verloren tabletten van Mosh'aru",
  d = "De trol met wie je hebt gesproken, vertelde niet de waarheid. In de twee tabletten die je voor hem hebt gehaald, staat dat ze de essentie van Hakkar bevatten. Maar er zit meer achter die legende. Ik heb lang gestudeerd en ontdekt dat er zes tabletten van Mosh'aru zijn, niet twee! Zes!$B$BEn ik vrees dat de geheimen van de andere tabletten ons niet zullen bevallen...$B$BZoek de derde en vierde tablet van Mosh'aru. Ze zijn in de Eastern Plaguelands, in handen van de mossflayer-trollen. Zoek ze en breng ze naar mij.",
  o = "Breng de Third Mosh'aru Tablet en de Fourth Mosh'aru Tablet naar Prospector Ironboot in Tanaris.",
  p = "Heb je de tabletten? Ik vrees dat hun teksten een grote dreiging voor onze wereld zullen onthullen.",
  c = "Je hebt ze gevonden! Geweldig!$B$BDank je, $N. Ik ga deze teksten grondig bestuderen en hun betekenis ontcijferen.$B$BMaar voor jou heb ik een andere taak...",
  g = { {"tabletten", "tablets (tablet)"}, {"essentie", "essence"}, {"bevatten", "contain"}, {"er zit meer achter", "there is more to it"}, {"legende", "legend"}, {"vrees", "fear (vrezen)"}, {"bevallen", "to please, to be liked"}, {"in handen van", "in the hands of, held by"}, {"dreiging", "threat"}, {"onthullen", "reveal"}, {"grondig", "thoroughly"}, {"ontcijferen", "decipher"} },
},

[5248] = { en = "Tormented By the Past", tier = 4,
  t = "Gekweld door het verleden",
  d = "$N, ik huil om wat er in het verleden is gebeurd. Net als dit kristal zijn de elfen als volk in stukken gebroken. Ik weet niet of de stukken ooit weer één geheel zullen worden. Maar mijn verdriet is wat minder geworden, omdat ik je met deze ene kleine taak kon helpen.$B$BWe mogen het verleden niet vergeten, $N...$B$BBreng het Crystal of Zin-Malor alsjeblieft terug naar Lake Kel'Theril. Je moet een highborne-geest vinden die beseft welke fout er zo lang geleden is gemaakt. Laat de geest zien dat we de dingen weer goed hebben gemaakt.",
  o = "Breng het Crystal of Zin-Malor naar Lake Kel'Theril in Winterspring en zoek een highborne-geest die met je wil praten.",
  p = "Vervloekt... Voor altijd...",
  c = "Alsjeblieft, laat me alleen...",
  g = { {"gekweld", "tormented (kwellen)"}, {"huil", "weep, cry (huilen)"}, {"kristal", "crystal"}, {"volk", "people, race"}, {"geheel", "whole"}, {"verdriet", "sorrow, grief"}, {"beseft", "realizes (beseffen)"}, {"fout", "mistake, error"}, {"vervloekt", "cursed"}, {"voor altijd", "forever"} },
},

[5845] = { en = "Of Lost Honor", tier = 4,
  t = "Verloren eer",
  d = "De Order of the Silver Hand werd volledig vernietigd toen Uther werd gedood.$B$BDe jongen verzette zich zo lang hij kon. Hij werd teruggedreven naar het door oorlog verwoeste gehucht Northdale, waar hij zijn laatste gevecht leverde.$B$BWas er nog iemand van de Order in leven, dacht hij - en maakte het nog uit?$B$BMet die gedachte gooide Taelan de banier van de Order neer en deed hij afstand van alles wat hij had gekend. Zijn eer bleef achter op de met bloed doordrenkte grond van Northdale.$B$BJe moet naar Northdale reizen en dat symbool van verloren eer terughalen.",
  o = "Reis naar Northdale, in het noordoosten van de Eastern Plaguelands, en haal het Symbol of Lost Honor terug. Keer terug naar Tirion Fordring als je opdracht klaar is.",
  p = "Mijn geloof zal je leiden, $N. Het Licht kent geen grenzen.",
  c = "Het is nu nog even prachtig - zelfs zo gescheurd - als op de dag dat ik het voor het eerst zag en mijn eed van trouw aflegde.$B$BZijn verlossing komt eraan, en misschien de mijne ook...",
  g = { {"eer", "honor"}, {"verzette zich", "resisted, held out (zich verzetten)"}, {"teruggedreven", "pushed back (terugdrijven)"}, {"verwoeste", "ruined, devastated (verwoesten)"}, {"gehucht", "hamlet"}, {"banier", "banner, standard"}, {"afstand", "distance; afstand doen van = to renounce"}, {"doordrenkte", "soaked"}, {"geloof", "faith"}, {"gescheurd", "torn, tattered"}, {"eed van trouw", "oath of allegiance"}, {"aflegde", "took (an oath) (afleggen)"}, {"verlossing", "redemption"} },
},

[5846] = { en = "Of Love and Family", tier = 4,
  t = "Liefde en familie",
  d = "Toen Taelan een kind was, gingen we vaak met het gezin op uitstapje naar Caer Darrow. Bij ons laatste bezoek schilderde een kunstenaar met de naam Renfray een portret van ons, terwijl we op het strand poseerden. Het is mijn dierbaarste herinnering aan Taelan en Karandra allebei. Want op dat moment, met mijn vrouw en zoon in mijn armen, voelde ik een band van liefde en familie die ik nooit meer zou kennen.$B$BAls dit schilderij nog bestaat, moet je het vinden.$B$BReis naar het verwoeste eiland Caer Darrow en kijk of het schilderij of de kunstenaar er nog is.",
  o = "Reis naar het eiland Caer Darrow, in het zuidelijke midden van de Plaguelands, en zoek naar aanwijzingen over waar het schilderij is.",
  c = "Hoe kon ik het vergeten? Veel geesten op dit eiland zijn vervloekt. Ze moeten hun laatste gelukkige herinnering steeds opnieuw beleven, van vlak voor hun tragische einde.$B$BIk ben ook vervloekt, maar niet zoals zij - ik ben een van de weinigen die zich alles herinnert...$B$BMisschien is dit ding dat je me vraagt de reden dat ik in deze ruïnes rondspook. Misschien maakt dit ding dat ik je vertel me vrij.",
  g = { {"gezin", "family (household)"}, {"uitstapje", "outing, trip"}, {"kunstenaar", "artist"}, {"poseerden", "posed (poseren)"}, {"dierbaarste", "fondest, most cherished (dierbaar)"}, {"band", "bond"}, {"verwoeste", "ruined (verwoesten)"}, {"aanwijzingen", "clues (aanwijzing)"}, {"beleven", "to live through, experience"}, {"tragische", "tragic"}, {"ruïnes", "ruins"}, {"rondspook", "haunt (rondspoken)"}, {"maakt ... vrij", "sets free (vrijmaken)"} },
},

[6026] = { en = "That's Asking A Lot", tier = 4,
  t = "Dat is veel gevraagd",
  d = "Die mensen van de Argent Dawn hier hebben de oude Smokey ingehuurd voor wat sloopwerk. Smokey's moeder heeft geen domoor grootgebracht. Als er goud op tafel komt, staat Smokey voor je klaar. Dat is mijn motto!$B$BIk wil de beloning best met je delen, als jij wat loopwerk wilt doen. Dit is de afspraak: ik ga naar Plaguewood en markeer de gebouwen die we moeten vernietigen. Jij verzamelt de onderdelen voor de bommen. We zien elkaar hier weer als je alles hebt. Afgesproken?",
  o = "Smokey LaRue wil dat je 2 Thorium Bars, 1 Golden Rod, 8 Hi-Explosive Bombs en 8 Unstable Triggers haalt.$B$BVoor deze voorwerpen moet je een smid en een ingenieur zoeken.",
  p = "Vertrouw de oude Smokey maar, $r. De beloning is het waard. Die Argent Dawn-mensen maken geen grapjes als het om betalen gaat.$b",
  c = "Ik kan je de helft vooraf betalen en de helft als de klus klaar is.",
  g = { {"ingehuurd", "hired (inhuren)"}, {"sloopwerk", "demolition work"}, {"domoor", "dummy, fool"}, {"grootgebracht", "raised (grootbrengen)"}, {"staat ... voor je klaar", "is at your service"}, {"loopwerk", "legwork"}, {"afspraak", "deal, agreement"}, {"markeer", "mark (markeren)"}, {"onderdelen", "parts, components"}, {"afgesproken", "deal, agreed"}, {"smid", "blacksmith"}, {"ingenieur", "engineer"}, {"maken geen grapjes", "don't mess around"}, {"vooraf", "in advance, up front"}, {"klus", "job"} },
},

[6041] = { en = "When Smokey Sings, I Get Violent", tier = 4,
  t = "Als Smokey zingt, word ik gewelddadig",
  d = "Terwijl jij de spullen verzamelde, heb ik een paar van mijn mensen de Scourge-gebouwen laten markeren die we moeten slopen.$B$BDit is het plan: ik geef je tien staven van mijn speciale mengsel. Die breng je naar Plaguewood. Daar plaats je ze in de Scourge-gebouwen die ik heb laten markeren om op te blazen.$B$B<Smokey knipt met zijn vingers.>$B$BBing! Zo makkelijk is het.",
  o = "Reis naar Plaguewood, ten noordwesten van Light's Hope. Vernietig 8 Scourge Structures door Smokey's Special Compound te gebruiken bij de Mark of Detonation in elk gebouw. Smokey heeft de Ziggurats en Slaughterhouses laten markeren.$B$BAls je de bom hebt geplaatst, verlaat je het gebouw en bewonder je je werk.$B$BTrouwens, Smokey's Special Compound is nogal... onstabiel.",
  p = "Ik heb nog spullen over om een paar extra staven van het speciale mengsel te maken. Zeg het maar tegen de oude Smokey als je er meer nodig hebt.",
  c = "Je bent veel donkerder dan ik me herinner. Je hebt die blik; de blik die zegt: 'Ik ben verkoold door een zware explosieve bom.'$B$B<Smokey lacht.>$B$BHoe dan ook! Hier is jouw deel van de buit. Ik heb er iets extra's bij gedaan om de brandwonden te verzachten.",
  o1 = "Scourge Structures vernietigd",
  g = { {"gewelddadig", "violent"}, {"slopen", "demolish"}, {"staven", "sticks, bars (staaf)"}, {"mengsel", "mixture, compound"}, {"op te blazen", "to blow up (opblazen)"}, {"knipt", "snaps (knippen)"}, {"bewonder", "admire (bewonderen)"}, {"trouwens", "by the way"}, {"onstabiel", "unstable"}, {"verkoold", "charred (verkolen)"}, {"explosieve", "explosive"}, {"buit", "loot"}, {"brandwonden", "burns (brandwond)"}, {"verzachten", "soothe, ease"} },
},

[5206] = { en = "Marauders of Darrowshire", tier = 4,
  t = "Plunderaars van Darrowshire",
  d = "Chromie zei dat de relikwieën die je hebt verzameld ingrediënten zijn voor een krachtige spreuk. Er is nog één ding nodig: schedels van de Scourge die meevochten in de slag om Darrowshire.$B$BNeem dit kristal en jaag op Scourge-kampioenen voor hun schedels. Het kristal is betoverd. Als een kampioen in de slag meevocht, gaat het kristal resoneren wanneer je het over zijn schedel beweegt. Breng me die resonerende schedels.$B$BGa, $N. Je vindt Scourge-kampioenen in de Noxious Glade in het noorden en de Fungal Vale in het westen.",
  o = "Breng 5 Resonating Skulls en het Mystic Crystal naar Carlin Redpath in de Eastern Plaguelands.",
  p = "Heb je de schedels? Chromie zei dat ze heel belangrijk zijn voor haar spreuk. En die spreuk geeft ons de kans om Darrowshire te redden.",
  c = "Je hebt ze gevonden! Geweldig!$b$bIk begrijp niet helemaal hoe ze ons kunnen helpen. Maar ik voel hun kracht, en ik weet diep vanbinnen dat ze verbonden zijn met mijn geboortedorp Darrowshire.",
  g = { {"plunderaars", "marauders (plunderaar)"}, {"relikwieën", "relics (relikwie)"}, {"ingrediënten", "ingredients, reagents"}, {"spreuk", "spell"}, {"schedels", "skulls (schedel)"}, {"meevochten", "fought along, took part (meevechten)"}, {"slag", "battle"}, {"kampioenen", "champions (kampioen)"}, {"betoverd", "enchanted (betoveren)"}, {"resoneren", "resonate"}, {"diep vanbinnen", "deep down, in my bones"}, {"verbonden", "linked, connected"}, {"geboortedorp", "home village, village of birth"} },
},

[5264] = { en = "Lord Maxwell Tyrosus", tier = 4,
  t = "Lord Maxwell Tyrosus",
  d = "Ik sta op het punt je een grote eer te verlenen, $N.$B$BLord Maxwell wil je belonen voor je dienst aan de Argent Dawn!$B$BHet is jaren geleden dat Maxwell buitenstaanders heeft ontvangen.$b",
  o = "Spreek met Lord Maxwell Tyrosus. Hij is in de kerk.",
  c = "Je bent een waardige bondgenoot, $N. Je zult de vruchten plukken van je trouwe toewijding.",
