[5265] = { en = "The Argent Hold", tier = 4,
  t = "De Argent Hold",
  d = "Al jaren is de Argent Hold op slot gebleven. Niemand was waardig genoeg om erin te reiken en de kracht van de Argent Dawn eruit te nemen - tot vandaag.$B$BDe Argent Hold staat nu voor je open, $N.",
  o = "Open de Argent Hold en neem je beloning.",
