[5281] = { en = "The Restless Souls", tier = 4,
  t = "De rusteloze zielen",
  d = "Sommigen stierven op tragische wijze bij de val van Stratholme. Velen maakten zelf een einde aan hun leven. Ze stortten zich liever in de vele vlammen van de smeulende stad dan dat ze een van de Scourge werden.$B$BNu lopen ze als rusteloze geesten door de straten van Stratholme.$B$BWe moeten ze helpen, $N!$B$BIk heb een collega, Egan, die wonderbaarlijk werk doet met geesten en zielen. Zoek hem op. Hij loopt rond in het oosten van de Plaguelands, bij Stratholme, en test er zijn uitvindingen.",
  o = "Zoek Egan. Je weet alleen dat hij voor het laatst bij Stratholme is gezien.",
  c = "Dus Alen heeft eindelijk iemand gevonden die dapper genoeg is, hè?",
  g = { {"rusteloze", "restless"}, {"zielen", "souls (ziel)"}, {"op tragische wijze", "tragically"}, {"val", "fall"}, {"stortten zich", "threw themselves (zich storten)"}, {"smeulende", "smoldering (smeulen)"}, {"collega", "colleague, associate"}, {"wonderbaarlijk", "miraculous"}, {"uitvindingen", "inventions, innovations"}, {"dapper", "brave"} },
},

[5464] = { en = "Menethil's Gift", tier = 4,
  t = "Het geschenk van Menethil",
  d = "De ziel van de gevallene klampt zich vast aan wat zijn vroegere leven voorstelt. Hij verandert het voorwerp in een aan de ziel gebonden aandenken. Je pakt het voorwerp op en stopt het in je tas.",
  o = "Breng het Soulbound Keepsake naar Leonid Barthalomew in de Eastern Plaguelands.",
  p = "<Leonid huivert.>",
  c = "Zoals de ziel zich aan het aandenken vastklampte, zo zal hij zich vastklampen aan het lichaam van Ras Frostwhisper.",
  g = { {"geschenk", "gift"}, {"gevallene", "the fallen one"}, {"klampt zich vast", "clings (zich vastklampen)"}, {"vroegere", "former"}, {"voorstelt", "represents (voorstellen)"}, {"gebonden", "bound"}, {"aandenken", "keepsake, memento"}, {"huivert", "shudders (huiveren)"}, {"vastklampte", "clung (zich vastklampen)"}, {"lichaam", "body, physical form"} },
},

[5513] = { en = "Mantles of the Dawn", tier = 4,
  t = "De mantels van de Dawn",
  d = "Je dienst aan de Argent Dawn verdient lof, $N. Je wordt bij ons echt vereerd. Ik heb toestemming gekregen om je een van de waardevolste voorwerpen van de Dawn te laten kopen: onze mantels die beschermen tegen magie.$B$BAls je een mantel aan je huidige schouderstuk toevoegt, word je op een van vijf mogelijke manieren beter bestand tegen de krachten van de magie. Als teken van blijvende toewijding aan onze zaak vraag ik minstens tien van onze Valor Tokens in ruil voor toegang tot deze mantels.",
  o = "Breng 10 Argent Dawn Valor Tokens naar Quartermaster Breechlock in Light's Hope Chapel, Eastern Plaguelands.",
  p = "Ah, nobele $C! Heb je de Valor Tokens bij je waar ik om vroeg? Zodra je ze aan mij geeft, kun je onze verschillende mantels bij mij kopen.",
  c = "Uitstekend - je eerbetoon aan de Dawn is genoteerd, $N. Nu dit gedaan is, ben ik blij dat je onze mantels kunt kopen. Zolang je je huidige status bij ons behoudt, kun je deze mantels kopen bij elke erkende kwartiermeester van de Argent Dawn.$B$BVoor de Dawn, $gmijn broeder:mijn zuster;!",
  g = { {"mantels", "mantles (mantel)"}, {"verdient lof", "deserves praise, is to be commended"}, {"vereerd", "revered (vereren)"}, {"toestemming", "permission, authorization"}, {"waardevolste", "most valuable"}, {"schouderstuk", "shoulder piece"}, {"bestand tegen", "resistant to"}, {"toewijding", "dedication"}, {"zaak", "cause"}, {"in ruil voor", "in exchange for"}, {"nobele", "noble"}, {"eerbetoon", "tribute"}, {"genoteerd", "noted (noteren)"}, {"behoudt", "keep, maintain (behouden)"}, {"erkende", "authorized, recognized"}, {"kwartiermeester", "quartermaster"} },
},

[5517] = { en = "Chromatic Mantle of the Dawn", tier = 4,
  t = "De Chromatic Mantle of the Dawn",
  d = "$gBroeder:Zuster; $N - je daden voor de Argent Dawn zijn veel te talrijk om makkelijk op te noemen. Als passend eerbetoon geef ik je een van onze speciale Chromatic Mantles of the Dawn. Deze versie beschermt de drager tegelijk tegen alle soorten magie waartegen je je kunt beschermen. Chromatic Mantles of the Dawn zijn alleen voor de machtigste helden van de Dawn!$B$BBreng me vijfentwintig Valor Tokens als teken van eerbetoon, en ik geef je de beste van al onze mantels.",
  o = "Breng 25 Argent Dawn Valor Tokens naar Quartermaster Breechlock in Light's Hope Chapel, Eastern Plaguelands.",
  p = "Gegroet, machtige $c! Heb je de Valor Tokens bij je waar ik om vroeg? Zodra je ze aan mij geeft, krijg je je eigen Chromatic Mantle of the Dawn.",
  c = "Zeer indrukwekkend, $N - de Chromatic Mantle of the Dawn is nu van jou!$B$BZolang je Exalted blijft bij de Argent Dawn, kun je extra Chromatic Mantles kopen. Je kunt ze meteen krijgen bij elke kwartiermeester van de Dawn.",
  g = { {"daden", "deeds (daad)"}, {"talrijk", "numerous"}, {"op te noemen", "to list, recount (opnoemen)"}, {"passend", "fitting"}, {"eerbetoon", "tribute"}, {"drager", "wearer"}, {"tegelijk", "at the same time, simultaneously"}, {"machtigste", "mightiest"}, {"helden", "heroes (held)"}, {"gegroet", "greetings, salutations"}, {"indrukwekkend", "impressive"}, {"kwartiermeester", "quartermaster"} },
},

[5721] = { en = "The Battle of Darrowshire", tier = 4,
  t = "De slag om Darrowshire",
  d = "Nu, $N, ga je meedoen aan de slag om Darrowshire, en je gaat Joseph Redpath redden.$B$BLeg deze bundel relikwieën op het dorpsplein van Darrowshire, en de geesten van Darrowshire zullen opstaan. Vecht met hen mee en zorg dat deze twee dingen gebeuren: Davil moet blijven leven tot na de dood van Horgus, en Redpath moet blijven leven tot hij verdorven wordt, en dan verslagen.$B$BNadat je de verdorven Redpath hebt verslagen, wordt zijn geest gered. Spreek met hem en ga daarna terug naar zijn dochter Pamela.",
  o = "Leg de Relic Bundle op het dorpsplein van Darrowshire.$B$BVoorkom dat Davil Lightfire sterft vóór de dood van Horgus.$B$BVoorkom dat Captain Redpath sterft voordat Redpath the Corrupted verschijnt.$B$BVersla Redpath the Corrupted.$B$BSpreek met de geest van Joseph Redpath als hij op het dorpsplein verschijnt. Spreek daarna met Pamela in haar huis.",
  p = "Ik denk dat ik buiten spoken hoorde. Ze fluisteren enge dingen tegen me...",
  c = "Het vechten is voorbij! Ik hoorde mijn papa iets tegen me fluisteren. Hij heeft alle spoken weggejaagd en hij zegt dat hij naar huis komt! Ik ben zo blij!$B$BHij zei ook dat ik je welkom moest heten als je naar ons huis kwam, dus ik heb thee gemaakt!$B$BIk hoop dat je van veel suiker houdt!",
  e = "Aanvaard de vergeving van Redpath",
  g = { {"slag", "battle"}, {"bundel", "bundle"}, {"relikwieën", "relics (relikwie)"}, {"dorpsplein", "town square"}, {"opstaan", "rise"}, {"verdorven", "corrupted"}, {"verslagen", "defeated (verslaan)"}, {"voorkom", "prevent (voorkomen)"}, {"verschijnt", "appears (verschijnen)"}, {"spoken", "ghosts (spook)"}, {"fluisteren", "whisper"}, {"enge", "scary (eng)"}, {"weggejaagd", "chased away (wegjagen)"}, {"welkom heten", "to welcome"}, {"aanvaard", "accept (aanvaarden)"}, {"vergeving", "forgiveness"} },
},

[5941] = { en = "Return to Chromie", tier = 4,
  t = "Terug naar Chromie",
  d = "Je hebt veel relikwieën van de slag om Darrowshire verzameld. Elke keer dat je met meer terugkwam, verlangde mijn hart naar mijn dorp... verlangde ik ernaar het te beschermen tegen zijn lot.$B$BIk weet dat dat niet kan. Maar Chromie, die vreemde gnoom in Andorhal, zegt dat het wel mogelijk is. Ze zegt dat jij Darrowshire kunt redden!$B$BZe vroeg me om de relikwieën bij elkaar te brengen en jou ze naar haar te laten brengen. Ze zei dat ze op je wacht in de verwoeste herberg van Andorhal.",
  o = "Breng de Bundle of Relics naar Chromie in Andorhal.",
  p = "Ik heb contact gehad met je vriend Carlin. Hij voelt veel pijn om het noodlot van zijn dorp, maar hij spreekt erg goed over jou en weet dat jij de dingen kunt rechtzetten.$b$bO, maar ik dwaal af van het onderwerp... $N, heb je de relikwieën waar ik om vroeg?",
  c = "Ah ja, daar zijn ze. Samen vormen ze een krachtige spreuk, een spreuk die de geesten van Darrowshire zal oproepen.$b$bMet die spreuk, en met een beetje geluk, kunnen we Joseph Redpath redden!",
  g = { {"relikwieën", "relics (relikwie)"}, {"verlangde", "yearned, longed (verlangen)"}, {"lot", "fate"}, {"gnoom", "gnome"}, {"verwoeste", "ruined (verwoesten)"}, {"herberg", "inn"}, {"noodlot", "doom, fate"}, {"rechtzetten", "set right"}, {"dwaal af", "drift off, stray (afdwalen)"}, {"onderwerp", "subject"}, {"vormen", "form, weave"}, {"spreuk", "spell"}, {"oproepen", "summon, raise"} },
},

[5942] = { en = "Hidden Treasures", tier = 4,
  t = "Verborgen schatten",
  d = "Papa zei dat ik je deze sleutel moest geven. Hij zei dat hij een kist opent, achter het huis.$B$BHij wilde ook dat ik je bedankte. Heb je hem een plezier gedaan? Heb je hem verteld dat je mijn pop hebt gevonden?$B$BNou, hier is de sleutel. En dank je wel, $N. Dank je wel! Je bent een heel aardige $gmeneer:mevrouw;!",
  o = "Breng Joseph's Key naar Joseph's Chest.",
  p = "Deze kist is oud en zit onder het vuil.",
  c = "De sleutel past in het slot, en de kist gaat open...",
  g = { {"verborgen", "hidden"}, {"schatten", "treasures (schat)"}, {"sleutel", "key"}, {"kist", "chest"}, {"een plezier gedaan", "done a favor"}, {"pop", "doll"}, {"aardige", "nice, kind (aardig)"}, {"vuil", "dirt, grime"}, {"slot", "lock"} },
},

[6024] = { en = "Hameya's Plea", tier = 4,
  t = "De smeekbede van Hameya",
  d = "Dood me. Voordat het te laat is.$B$BIk ben Hameya. Toen mijn broeders en ik naar Zul'Mashar reisden, aten we bedorven vlees... en we veranderden. We zijn besmet.$B$BIk kan de woorden van de lich nu voelen. Ze dringen erop aan dat ik Zul'Mashar bereik en meer van mijn volk besmet. Ik kan geen weerstand bieden, dus heb ik deze rol geschreven voordat mijn wil verdween.$B$BIk heb een kist in de aarde begraven, naast een wagen achter deze crypte, maar alleen mijn sleutel kan hem openen. Ik heb de sleutel. Als je mijn schat wilt, zoek mij dan.$B$BDood me. Voordat het te laat is.",
  o = "Dood Infiltrator Hameya. Gebruik zijn sleutel op de Mound of Dirt achter de Undercroft.",
  p = "De kist die hier begraven ligt, zit stevig op slot.",
  c = "De kist van Hameya is open!!",
  g = { {"smeekbede", "plea"}, {"broeders", "brethren, brothers (broeder)"}, {"bedorven", "rotten, spoiled"}, {"besmet", "infected"}, {"dringen erop aan", "urge, insist (aandringen)"}, {"bereik", "reach (bereiken)"}, {"weerstand bieden", "resist"}, {"rol", "scroll"}, {"wil", "will"}, {"begraven", "buried"}, {"wagen", "wagon"}, {"crypte", "crypt"}, {"stevig", "firmly, securely"} },
},

[6185] = { en = "The Eastern Plagues", tier = 4,
  t = "De oostelijke plagen",
  d = "Zoals ik al zei, is je eerste missie een verkenning. Niets bijzonders, $N. Je moet naar de Eastern Plaguelands reizen en zoeken naar aanwijzingen over deze Blightcaller.$B$BLet goed op informatie over onze vermiste agenten. We moeten aannemen dat ze dood zijn, en als ze dood zijn, moet er ergens een lijk liggen...$B$B<Flint slikt moeilijk.>$B$BAlle agenten van SI:7 dragen dit insigne.$B$B<Flint laat je zijn SI:7-insigne zien.>$B$BBreng alle insignes die je vindt naar mij terug.",
  o = "Doorzoek de Eastern Plaguelands naar aanwijzingen over de \"Blightcaller\" en de vermiste SI:7-agenten. Als je SI:7 Insignias vindt, breng ze dan terug naar Flint Shadowmore in Chillwind Camp.",
  p = "Al... Al iets gevonden??",
  c = "Rutger. Fredo. Turyen. Allemaal... dood...$B$B<Flint knijpt de insignes stevig in zijn hand.>$B$BWaar waren ze? Heb je nog meer informatie gevonden over die schoft, de Blightcaller?",
  e = "De Blightcaller ontmaskerd",
  g = { {"plagen", "plagues (plaag)"}, {"verkenning", "reconnaissance"}, {"aanwijzingen", "clues (aanwijzing)"}, {"vermiste", "missing"}, {"agenten", "agents, operatives (agent)"}, {"aannemen", "assume"}, {"lijk", "corpse"}, {"slikt", "swallows (slikken)"}, {"insigne", "insignia, badge"}, {"doorzoek", "search, scour (doorzoeken)"}, {"knijpt", "squeezes, clutches (knijpen)"}, {"schoft", "bastard, scoundrel"}, {"ontmaskerd", "unmasked, uncovered (ontmaskeren)"} },
},

[6187] = { en = "Order Must Be Restored", tier = 4,
  t = "De orde moet hersteld worden",
  d = "Weet je hoeveel ranger lords er in deze wereld bestaan? Hoeveel menselijke ranger lords er ooit hebben bestaan?$B$BWat Nathanos heeft bereikt, was nog nooit eerder gebeurd. Hij was een tactisch genie, verantwoordelijk voor overwinningen van de Alliance in tien jaar van strijd.$B$BEn nu... de kampioen van de Forsaken.$B$BNee. Dit kan niet. De orde moet hersteld worden.$B$BVerzamel een leger, $N. Ga met je leger terug naar de Plaguelands en vernietig de Blightcaller.$B$BIk wens je veel geluk, $N. Echt, dat heb je nodig voor deze strijd.",
  o = "Stel een leger samen en reis naar de Eastern Plaguelands. Voer een volledige aanval uit op Nathanos Blightcaller en op al het Horde-tuig dat hem probeert te beschermen.$B$BBlijf scherp, $N. De Horde zal de ranger lord met hun eigen leven verdedigen.",
  p = "<Highlord Bolvar Fordragon is diep in gedachten.>",
  c = "Het is een tragedie. Ik denk... Ik geloof dat ons volk vervloekt is, $N. We zijn vervloekt om onze grootste krijgers te verliezen; onze edelste helden; onze meest begaafde geleerden.$B$BWe staan bij je in het krijt, en ik verzeker je, $N: waar Nathanos Marris nu ook is, hij glimlacht op je neer.",
  g = { {"orde", "order"}, {"hersteld", "restored (herstellen)"}, {"bereikt", "achieved (bereiken)"}, {"tactisch genie", "tactical genius"}, {"verantwoordelijk", "responsible"}, {"overwinningen", "victories (overwinning)"}, {"stel ... samen", "assemble (samenstellen)"}, {"voer ... uit", "carry out, launch (uitvoeren)"}, {"tuig", "scum, filth"}, {"blijf scherp", "keep your wits about you"}, {"verdedigen", "defend"}, {"edelste", "noblest"}, {"begaafde", "gifted"}, {"geleerden", "scholars (geleerde)"}, {"in het krijt", "in debt (bij iemand in het krijt staan)"} },
},

[9121] = { en = "The Dread Citadel - Naxxramas", tier = 4,
  t = "De gevreesde citadel - Naxxramas",
  d = "Diep in Plaguewood ligt de ingang van de gevreesde citadel Naxxramas. Vroeger mislukte elke poging om binnen te komen, door de magische beschermingen op het runenportaal. Tot nu.$B$BWe hebben een manier bedacht om binnen te komen met een arcane vermomming - een oude spreuk van de Kirin Tor, met een paar aanpassingen van mezelf. Omdat je toewijding aan de zaak van de Dawn wat tekortschiet, $N, is de prijs hoog. Je mag weigeren en terugkomen als je Revered of Exalted bent, voor korting.",
  o = "Archmage Angela Dosantos in Light's Hope Chapel in de Eastern Plaguelands wil 5 Arcane Crystals, 2 Nexus Crystals, 1 Righteous Orb en 60 goudstukken. Je moet ook Honored zijn bij de Argent Dawn.$b",
  p = "Niemand is Naxxramas binnengegaan en heeft het overleefd om het na te vertellen.",
  c = "Je zult een lichte tinteling voelen, $N. Dat gevoel betekent dat het werkt. Als het klaar is, kun je Naxxramas binnengaan door op het runenportaal in Plaguewood te stappen.$b",
  g = { {"gevreesde", "dreaded (gevreesd)"}, {"citadel", "citadel, fortress"}, {"mislukte", "failed (mislukken)"}, {"poging", "attempt"}, {"beschermingen", "wards, protections"}, {"runenportaal", "rune portal"}, {"vermomming", "disguise, cloaking"}, {"aanpassingen", "modifications (aanpassing)"}, {"tekortschiet", "falls short, is lacking (tekortschieten)"}, {"weigeren", "decline, refuse"}, {"korting", "discount"}, {"goudstukken", "gold pieces"}, {"na te vertellen", "to tell the tale (navertellen)"}, {"tinteling", "tingle"} },
},

[9122] = { en = "The Dread Citadel - Naxxramas", tier = 4,
  t = "De gevreesde citadel - Naxxramas",
  d = "Diep in Plaguewood ligt de ingang van de gevreesde citadel Naxxramas. Vroeger mislukte elke poging om binnen te komen, door de magische beschermingen op het runenportaal. Tot nu.$B$BWe hebben een manier bedacht om binnen te komen met een soort blijvende arcane vermomming - een oude spreuk van de Kirin Tor, met een paar aanpassingen van mezelf. Maar de vermomming is duur. Omdat je toewijding aan de zaak van de Dawn bewonderenswaardig is, willen we een deel van die kosten op ons nemen.",
  o = "Archmage Angela Dosantos in Light's Hope Chapel in de Eastern Plaguelands wil 2 Arcane Crystals, 1 Nexus Crystal en 30 goudstukken. Je moet ook Revered zijn bij de Argent Dawn.",
  p = "Niemand is Naxxramas binnengegaan en heeft het overleefd om het na te vertellen.",
  c = "Je zult een lichte tinteling voelen, $N. Dat gevoel betekent dat het werkt. Als het klaar is, kun je Naxxramas binnengaan door op het runenportaal in Plaguewood te stappen.$b",
  g = { {"gevreesde", "dreaded (gevreesd)"}, {"poging", "attempt"}, {"beschermingen", "wards, protections"}, {"runenportaal", "rune portal"}, {"blijvende", "permanent, lasting"}, {"vermomming", "disguise, cloaking"}, {"aanpassingen", "modifications (aanpassing)"}, {"bewonderenswaardig", "admirable"}, {"op ons nemen", "take on ourselves, bear"}, {"goudstukken", "gold pieces"}, {"na te vertellen", "to tell the tale (navertellen)"}, {"tinteling", "tingle"} },
},

[9123] = { en = "The Dread Citadel - Naxxramas", tier = 4,
  t = "De gevreesde citadel - Naxxramas",
  d = "Diep in Plaguewood ligt de ingang van de gevreesde citadel Naxxramas. Vroeger mislukte elke poging om binnen te komen, door de magische beschermingen op het runenportaal. Tot nu.$B$BWe hebben een manier bedacht om binnen te komen met een soort blijvende arcane vermomming - een oude spreuk van de Kirin Tor, met een paar aanpassingen van mezelf. Maar de vermomming is duur; jouw toewijding aan de zaak van de Dawn is echter onwankelbaar! We laten alle kosten vallen.",
  o = "Archmage Angela Dosantos in Light's Hope Chapel in de Eastern Plaguelands geeft je gratis Arcane Cloaking. Je moet Exalted zijn bij de Argent Dawn.",
  p = "Niemand is Naxxramas binnengegaan en heeft het overleefd om het na te vertellen.",
  c = "Je zult een lichte tinteling voelen, $N. Dat gevoel betekent dat het werkt. Als het klaar is, kun je Naxxramas binnengaan door op het runenportaal in Plaguewood te stappen.",
  g = { {"gevreesde", "dreaded (gevreesd)"}, {"poging", "attempt"}, {"beschermingen", "wards, protections"}, {"runenportaal", "rune portal"}, {"blijvende", "permanent, lasting"}, {"vermomming", "disguise, cloaking"}, {"echter", "however"}, {"onwankelbaar", "unwavering"}, {"laten ... vallen", "drop, waive (laten vallen)"}, {"gratis", "free, at no cost"}, {"na te vertellen", "to tell the tale (navertellen)"}, {"tinteling", "tingle"} },
},

[9124] = { en = "Cryptstalker Armor Doesn't Make Itself...", tier = 4,
  t = "Cryptstalker-wapenrusting maakt zichzelf niet...",
  d = "Wil je zo'n glimmende munt verdienen?$B$B<Leopold houdt een insigne van de Crusade omhoog.>$B$BIk heb een probleempje waar jij me misschien mee kunt helpen, $N. Weet je, ik maak Cryptstalker-wapenrusting voor iedereen die dom genoeg is om Naxxramas in te gaan. Zij geven me de belangrijkste materialen voor de wapenrusting, maar de onderdelen van crypt fiends raken bij mij altijd op. Breng me een bundel onderdelen, dan betaal ik je met een insigne - te gebruiken bij de kwartiermeester.",
  o = "Huntsman Leopold in Light's Hope Chapel in de Eastern Plaguelands wil 30 Crypt Fiend Parts.",
  p = "Hoe gaat de jacht?",
  c = "Ah, dat is prima, $N. Onthoud: ik neem altijd graag meer onderdelen aan. Voor elke bundel die je me brengt, beloon ik je met een insigne.",
  g = { {"wapenrusting", "armor"}, {"glimmende", "shiny (glimmend)"}, {"munt", "coin"}, {"insigne", "insignia"}, {"probleempje", "little problem"}, {"dom", "stupid, daft"}, {"materialen", "materials (materiaal)"}, {"onderdelen", "parts (onderdeel)"}, {"raken ... op", "run out (opraken)"}, {"bundel", "bundle"}, {"kwartiermeester", "quartermaster"}, {"jacht", "hunt"}, {"beloon", "reward (belonen)"} },
},

[9125] = { en = "Crypt Fiend Parts", tier = 4,
  t = "Onderdelen van crypt fiends",
  p = "Je hebt uitstekend werk geleverd met de eerste bundel, $N. Als je er meer hebt, neem ik ze nu aan. Voor elke bundel die je inlevert, beloon ik je met nog een insigne.",
  c = "Prima, $n! Deze komen zeker goed van pas.",
  g = { {"onderdelen", "parts (onderdeel)"}, {"uitstekend", "excellent, exemplary"}, {"geleverd", "delivered, done (leveren)"}, {"bundel", "bundle"}, {"inlevert", "turn in, hand in (inleveren)"}, {"insigne", "insignia"}, {"van pas", "useful (van pas komen = come in handy)"} },
},

[9126] = { en = "Bonescythe Digs", tier = 4,
  t = "Graven voor Bonescythe",
  d = "Het patroon van Don Julio voor Bonescythe-wapenrusting heeft botfragmenten nodig - heel veel botfragmenten. De mensen die gek genoeg zijn om Naxxramas in te gaan, geven me genoeg van de belangrijkste materialen om de wapenrusting te maken. Maar ik zoek altijd meer botfragmenten van de Scourge.$B$BDus wat denk je? Heb je zin om je handen vuil te maken en tegelijk wat Scourge te vernietigen? Iedereen wint erbij.",
  o = "Rohan the Assassin in Light's Hope Chapel in de Eastern Plaguelands wil 30 Bone Fragments.$b",
  p = "Ik kan je de weg wijzen naar plekken vol skeletten, $c.",
  c = "Je werkt snel, $N. Snel als een vos... Zeg, heb ik je ooit verteld over de keer dat ik in een barbershopkwartet zat?$B$BHerinner me eraan dat ik je dat verhaal een keer vertel.",
  g = { {"graven", "dig"}, {"patroon", "pattern"}, {"wapenrusting", "armor"}, {"botfragmenten", "bone fragments"}, {"je handen vuil te maken", "to get your hands dirty"}, {"tegelijk", "at the same time"}, {"iedereen wint erbij", "everyone wins, win-win"}, {"de weg wijzen", "show the way, give directions"}, {"skeletten", "skeletons (skelet)"}, {"vos", "fox"}, {"barbershopkwartet", "barbershop quartet"}, {"herinner", "remind (herinneren)"} },
},

[9127] = { en = "Bone Fragments", tier = 4,
  t = "Botfragmenten",
  p = "Iemand in mijn vak kan nooit te veel botfragmenten hebben, $N. Als je botfragmenten over hebt, breng ze dan naar mij, dan beloon ik je met nog een insigne.",
  c = "Mijn droom om fulltime danser te worden in de disco van Gadgetzan komt binnenkort uit! Ga zo door, $n.",
  g = { {"botfragmenten", "bone fragments"}, {"vak", "trade, line of work"}, {"over hebt", "have left over (over hebben)"}, {"beloon", "reward (belonen)"}, {"insigne", "insignia"}, {"droom", "dream"}, {"danser", "dancer"}, {"komt ... uit", "comes true (uitkomen)"}, {"ga zo door", "keep it up"} },
},

[9128] = { en = "The Elemental Equation", tier = 4,
  t = "De elementaire vergelijking",
  d = "Gegroet, avonturier! Heb je interesse in wat werk? Wie voor mij werkt, betaal ik met insignes. Met deze insignes kun je bij de kwartiermeester krachtige voorwerpen kopen.$B$BJe hoeft alleen maar zoveel Core of Elements naar me te brengen als je kunt dragen. Hoe meer, hoe beter!$B$BJe vindt ze bij elementaire wezens in allerlei vormen en maten, overal in onze wereld.",
  o = "Archmage Angela Dosantos in Light's Hope Chapel in de Eastern Plaguelands wil 30 Core of Elements.$b",
  p = "Ik kan je alleen de goede kant op sturen, $N.",
  c = "Goed gedaan, $N! Zoals beloofd is het insigne van jou. Onthoud alleen: er is nog veel meer waar dit vandaan komt...",
  g = { {"elementaire", "elemental"}, {"vergelijking", "equation"}, {"gegroet", "greetings"}, {"avonturier", "adventurer"}, {"insignes", "insignias (insigne)"}, {"kwartiermeester", "quartermaster"}, {"krachtige", "powerful"}, {"wezens", "beings, creatures (wezen)"}, {"vormen", "shapes (vorm)"}, {"maten", "sizes (maat)"}, {"de goede kant op sturen", "steer in the right direction"}, {"beloofd", "promised (beloven)"} },
},

[9129] = { en = "Core of Elements", tier = 4,
  t = "Kernen van de elementen",
  p = "Eerlijk gezegd gebruik ik de kernen om Frostfire-wapenrusting te maken. Het is de wapenrusting van de magiërs die in Naxxramas vechten. Zonder jou en anderen zoals jij zouden we deze oorlog zeker verliezen.$b$bDus breng me meer kernen, dan geef ik je meer insignes.",
  c = "Je bewijst ons een grote dienst, $n. Goed gedaan!",
  g = { {"kernen", "cores (kern)"}, {"eerlijk gezegd", "truth be told, honestly"}, {"wapenrusting", "armor"}, {"magiërs", "mages (magiër)"}, {"zeker", "surely, definitely"}, {"oorlog", "war"}, {"insignes", "insignias (insigne)"}, {"bewijst ... een dienst", "do a service (een dienst bewijzen)"} },
},

[9131] = { en = "Binding the Dreadnaught", tier = 4,
  t = "Het binden van de Dreadnaught",
  d = "Heb je ooit Dreadnaught-wapenrusting gezien, $c? Nee, natuurlijk niet. Je bent nog maar een $gjongen:meid; - een kleuter. Ik zeg je, het is prachtig.$B$BJe vraagt je waarschijnlijk af wat dit met jou te maken heeft, hè? Weet je wat, groentje: ik heb Dark Iron-schroot nodig, en ik wil betalen om er zoveel mogelijk van te krijgen.$B$BIk heb het schroot nodig om sets Dreadnaught voor onze kampioenen te maken. Breng me schroot en je wordt betaald.",
  o = "Korfax in Light's Hope Chapel in de Eastern Plaguelands wil 30 Dark Iron Scraps.",
  p = "<Korfax gromt naar je.>$B$BWat wil je? De weg weten? Die kan ik je wel wijzen...",
  c = "Dit is genoeg, voor nu. Als je meer krijgt, weet je me te vinden.",
  g = { {"binden", "bind"}, {"wapenrusting", "armor"}, {"kleuter", "toddler, tyke"}, {"prachtig", "glorious, beautiful"}, {"vraagt je ... af", "wonder (zich afvragen)"}, {"groentje", "greenhorn, scrub"}, {"schroot", "scrap metal"}, {"kampioenen", "champions (kampioen)"}, {"gromt", "growls (grommen)"}, {"wijzen", "show, point"} },
},

[9132] = { en = "Dark Iron Scraps", tier = 4,
  t = "Dark Iron-schroot",
  p = "Voor elke armvol schroot geef ik je een insigne - hoe meer, hoe beter. En nu uit mijn ogen, voordat ik je in tweeën splijt!$b",
  c = "Is dat alles wat je me brengt? Misschien hoorde je me de eerste keer niet. Ik heb MEER nodig!",
  g = { {"schroot", "scrap metal"}, {"armvol", "armful"}, {"insigne", "insignia"}, {"hoe meer, hoe beter", "the more the better"}, {"uit mijn ogen", "out of my sight"}, {"in tweeën", "in two"}, {"splijt", "split, cleave (splijten)"} },
},

})

